  /* Align common theme tokens so native blocks inherit the palette */
  --foreground: #091324;
  --card-foreground: #091324;
  --popover-foreground: #091324;
  --primary: #1c3564;
  --muted-foreground: #091324;

  /* Filled navigation_button CTAs (Continue, Start Course, Finish, etc.) */
  --uaoa-cta: #F1A01F;
  --uaoa-cta-hover: #D35420;
}

